function api_call(string $method,string $path,?array $payload=null,string $token=''): array {
 $headers="Content-Type: application/json\r\n".(getenv('TRAILWATCH_TEST_SESSION_COOKIE')?"Cookie: ".getenv('TRAILWATCH_TEST_SESSION_COOKIE')."\r\nX-CSRF-Token: ".getenv('TRAILWATCH_TEST_CSRF_TOKEN')."\r\n":'');if($token!=='')$headers.="X-Bridge-Token: $token\r\n";
 $ctx=stream_context_create(['http'=>['method'=>$method,'header'=>$headers,'content'=>$payload===null?'':json_encode($payload,JSON_THROW_ON_ERROR),'ignore_errors'=>true,'timeout'=>8]]);
 $body=@file_get_contents($GLOBALS['base'].$path,false,$ctx);$line=$http_response_header[0]??'HTTP/1.1 500';return ['status'=>(int)substr($line,9,3),'body'=>is_string($body)?json_decode($body,true):null];
}
function expect_status(int $expected,array $response,string $label): void {if($response['status']!==$expected){fwrite(STDERR,"FAIL $label HTTP {$response['status']} ".json_encode($response['body'])."\n");exit(1);}echo "PASS $label HTTP {$response['status']}\n";}
function check(bool $ok,string $label): void {if(!$ok){fwrite(STDERR,"FAIL $label\n");exit(1);}echo "PASS $label\n";}
function queued_downlinks(string $nodeId,int $sequence,string $siteId='pup'): int {$q=db()->prepare("SELECT COUNT(*) FROM downlink_commands c JOIN hiker_nodes h ON h.id=c.hiker_node_id WHERE h.node_id=? AND c.site_id=? AND c.sequence_number=? AND c.status='QUEUED'");$q->execute([$nodeId,$siteId,$sequence]);return(int)$q->fetchColumn();}
function find_command(array $commands,string $nodeId,int $sequence): ?array {foreach($commands as $command)if($command['node_id']===$nodeId&&(int)$command['sequence_number']===$sequence)return$command;return null;}
function command_flags(int $commandId): array {$q=db()->prepare('SELECT test_mode,is_demo,is_rehearsal FROM downlink_commands WHERE id=?');$q->execute([$commandId]);return$q->fetch(PDO::FETCH_ASSOC)?:[];}
function downlink_status(string $nodeId,int $sequence,string $siteId='pup'): ?string {$q=db()->prepare('SELECT c.status FROM downlink_commands c JOIN hiker_nodes h ON h.id=c.hiker_node_id WHERE h.node_id=? AND c.site_id=? AND c.sequence_number=? ORDER BY c.id DESC LIMIT 1');$q->execute([$nodeId,$siteId,$sequence]);$v=$q->fetchColumn();return$v===false?null:(string)$v;}
